"""
高速入出力 & 競技プログラミング基本テンプレート (Fast I/O & Templates)
Generated by Gemini prior to contest (AtCoder Rule 20251003 compliant)

【概要・用途】
- fast_input(): sys.stdin.buffer.read().split() を使った超高速一括読み込みイテレータ
  大規模入力 (N >= 2 * 10^5) での TLE を防止。
- transpose(grid): 2次元配列の転置
- sys.setrecursionlimit(2000000): 再帰深さの拡大
"""

import sys

# https://github.com/ddfkit/acsampl/blob/main/inputt.py
# Generated by Gemini prior to contest (AtCoder Rule 20251003 compliant)
def fast_input():
    b=getattr(sys.stdin,'buffer',sys.stdin);d=b.read()
    if isinstance(d,str):d=d.encode()
    return iter(d.split())

# https://github.com/ddfkit/acsampl/blob/main/inputt.py
# Generated by Gemini prior to contest (AtCoder Rule 20251003 compliant)
def transpose(grid):
    return [list(x) for x in zip(*grid)]

if __name__ == "__main__":
    A = [[1, 2, 3], [4, 5, 6]]
    assert transpose(A) == [[1, 4], [2, 5], [3, 6]]

    import io
    fake_input = b"3 4\n1 2\n3 4\n5 6\n"
    sys.stdin = io.BytesIO(fake_input)
    it = fast_input()
    n = int(next(it)); m = int(next(it))
    pairs = [(int(next(it)), int(next(it))) for _ in range(n)]
    assert n == 3 and m == 4
    assert pairs == [(1, 2), (3, 4), (5, 6)]
    print("inputt.py: tests passed!")
